// ---- loot: When an enemy killed by the local player drops Dungeons loot. A drop is a coloured beam at the body; walk into it to pick it up. Enemy strength is read from max HP because Elden Ring has no elite flag the mod can read.
#[derive(Debug)]
pub struct LootRow {
    pub id: &'static str,
    pub source: &'static str,
    pub first_kill_only: bool,
    pub min_enemy_max_hp: i32,
    pub max_enemy_max_hp: i32,
    pub chance_pct: f32,
    pub min_rarity: &'static RarityRow,
    pub w_artifact: i32,
    pub w_weapon_enchant: i32,
    pub w_armor_enchant: i32,
    pub pickup_radius_m: f32,
    pub beam_ttl_s: f32,
}
