// ---- hooks: Every place the DLL touches the running game. Elden Ring 1.17.1 (exe 2.7.1.0) only: fromsoftware-rs main @59fbd3b ships RVAs for that build. Nothing is patched on disk; ModEngine2 loads the DLL.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HooksAccess { Read, Write, Call, Draw, Os }
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HooksTaskGroup { FrameBegin, ChrInsPostPhysics, DrawParamUpdate, Boot, Overlay, Any }
#[derive(Debug)]
pub struct HooksRow {
    pub id: &'static str,
    pub game_object: &'static str,
    pub access: HooksAccess,
    pub task_group: HooksTaskGroup,
    pub crate_api: &'static str,
    pub purpose: &'static str,
}
pub const HOOKS_GAME_VERSION: HooksRow = HooksRow { id: "game_version", game_object: "eldenring.exe version resource", access: HooksAccess::Read, task_group: HooksTaskGroup::Boot, crate_api: "eldenring git main @59fbd3b (Ww2710 = exe 2.7.1.0, Jp2711); crates.io 0.14.0 only knows 2.6.2.0, so the git pin is required", purpose: "Check the exe version ourselves first; on any other build log it and stay inactive instead of panicking" };
pub const HOOKS_TASK_RUNNER: HooksRow = HooksRow { id: "task_runner", game_object: "CSTask", access: HooksAccess::Call, task_group: HooksTaskGroup::Boot, crate_api: "CSTaskImp::wait_for_instance + run_recurring", purpose: "Run the mod's per-frame tasks inside the game loop" };
pub const HOOKS_MAIN_PLAYER: HooksRow = HooksRow { id: "main_player", game_object: "WorldChrMan.main_player (PlayerIns)", access: HooksAccess::Read, task_group: HooksTaskGroup::Any, crate_api: "WorldChrMan::instance", purpose: "Player position, orientation, handle, game data" };
pub const HOOKS_PLAYER_GAME_DATA: HooksRow = HooksRow { id: "player_game_data", game_object: "PlayerIns.player_game_data", access: HooksAccess::Write, task_group: HooksTaskGroup::FrameBegin, crate_api: "PlayerGameData.current_fp / current_hp / character_name / equipment.chr_asm", purpose: "FP cost of artifacts, heals, equipped gear handles, save key" };
pub const HOOKS_FOLLOW_CAMERA: HooksRow = HooksRow { id: "follow_camera", game_object: "WorldChrMan.chr_cam (ChrCam.pers_cam.matrix)", access: HooksAccess::Write, task_group: HooksTaskGroup::FrameBegin, crate_api: "ChrCam", purpose: "Pin the follow camera's yaw to the Dungeons yaw so movement is screen-relative" };
pub const HOOKS_RENDER_CAMERA: HooksRow = HooksRow { id: "render_camera", game_object: "CSCamera.pers_cam_1 (CSCam.matrix, fov)", access: HooksAccess::Write, task_group: HooksTaskGroup::DrawParamUpdate, crate_api: "CSCamera::instance_mut", purpose: "Draw the world from the Dungeons camera" };
pub const HOOKS_PLAYER_ORIENTATION: HooksRow = HooksRow { id: "player_orientation", game_object: "PlayerIns.chr_ins.modules.physics.orientation", access: HooksAccess::Write, task_group: HooksTaskGroup::ChrInsPostPhysics, crate_api: "CSChrPhysicsModule.orientation", purpose: "Turn the character toward the cursor when attacking" };
pub const HOOKS_PHYS_RAYCAST: HooksRow = HooksRow { id: "phys_raycast", game_object: "CSHavokMan.phys_world", access: HooksAccess::Call, task_group: HooksTaskGroup::DrawParamUpdate, crate_api: "CSPhysWorld::cast_ray", purpose: "Cursor ground point and ceiling avoidance" };
pub const HOOKS_BULLET_SPAWN: HooksRow = HooksRow { id: "bullet_spawn", game_object: "CSBulletManager", access: HooksAccess::Call, task_group: HooksTaskGroup::FrameBegin, crate_api: "CSBulletManager::spawn_bullet (BulletSpawnData mirrored with the same layout)", purpose: "Artifacts that throw, call or burst" };
pub const HOOKS_SPEFFECT_APPLY: HooksRow = HooksRow { id: "speffect_apply", game_object: "ChrIns", access: HooksAccess::Call, task_group: HooksTaskGroup::FrameBegin, crate_api: "ChrInsExt::apply_speffect", purpose: "Buff artifacts and Fire Aspect" };
