// ---- ui: Everything the mod draws. Overlay rows are ImGui windows drawn by hudhook; the beam is drawn into the world.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum UiKind { Overlay, World }
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum UiAnchor { BottomCenter, TopCenter, RightCenter, Cursor, World }
#[derive(Debug)]
pub struct UiRow {
    pub id: &'static str,
    pub kind: UiKind,
    pub anchor: UiAnchor,
    pub offset_x_px: i32,
    pub offset_y_px: i32,
    pub shown_when: &'static str,
    pub hook: &'static HooksRow,
    pub contents: &'static str,
}
